                '.page-content.contact-page[_ngcontent-%COMP%] {\n  padding: 0.5em 1.75em 2.5em 1.75em;\n}\n\n.contact-cards[_ngcontent-%COMP%] {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(14em, 1fr));\n  gap: 0.875em;\n}\n\n.contact-card[_ngcontent-%COMP%] {\n  font-size: 1em;\n  color: var(--font-1);\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  gap: 0.875em;\n  padding: 1em;\n  text-decoration: none;\n  transition: border-color 150ms ease, background-color 150ms ease;\n}\n\n@media (hover: hover) {\n  .contact-card[_ngcontent-%COMP%]:hover {\n    border-color: var(--blue-1);\n    background: var(--hover-alpha);\n  }\n}\n\n.contact-card-icon[_ngcontent-%COMP%] {\n  flex: 0 0 auto;\n  width: 2.75em;\n  height: 2.75em;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: var(--blue-1-alpha-2);\n  color: var(--blue-1);\n  font-size: 1.05em;\n}\n\n.contact-card-body[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n  gap: 0.1em;\n  min-width: 0;\n}\n\n.contact-card-label[_ngcontent-%COMP%] {\n  font-weight: bold;\n  color: var(--font-1);\n}\n\n.contact-card-sub[_ngcontent-%COMP%] {\n  color: var(--dark-blue-1);\n  font-size: 0.8125em;\n}\n\n.contact-card-value[_ngcontent-%COMP%] {\n  color: var(--blue-1);\n  font-weight: 600;\n  word-break: break-word;\n}\n\n.contact-note[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  gap: 0.45em;\n  color: var(--dark-blue-1);\n  font-size: 0.8125em;\n}\n\n.contact-note[_ngcontent-%COMP%]   a[_ngcontent-%COMP%] {\n  color: var(--dark-blue-1);\n  text-decoration: none;\n  font-weight: 600;\n}\n\n@media (hover: hover) {\n  .contact-note[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:hover {\n    color: var(--blue-1);\n  }\n}\n\n.contact-section[_ngcontent-%COMP%] {\n  font-size: 1em;\n  color: var(--font-1);\n  padding: 1.25em;\n}\n\n.contact-section[_ngcontent-%COMP%]   .fansly-section-title[_ngcontent-%COMP%] {\n  margin-top: 0;\n}\n\n.contact-subtitle[_ngcontent-%COMP%] {\n  font-weight: bold;\n  color: var(--font-1);\n  font-size: 0.9375em;\n}\n\n.contact-address[_ngcontent-%COMP%] {\n  color: var(--dark-blue-1);\n  line-height: 1.6;\n  margin-top: 0.25em;\n}\n\n.contact-section[_ngcontent-%COMP%]   a[_ngcontent-%COMP%] {\n  color: var(--blue-1);\n  text-decoration: none;\n}\n\n@media (hover: hover) {\n  .contact-section[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:hover {\n    text-decoration: underline;\n  }\n}\n\n.contact-processors[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5em;\n}\n\n.contact-processor[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  gap: 0.5em;\n  color: var(--dark-blue-1);\n  font-size: 0.875em;\n}\n\n.contact-processor-icon[_ngcontent-%COMP%] {\n  color: var(--dark-blue-1);\n}\n\n.contact-steps[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n  gap: 0.625em;\n  border-left: 2px solid var(--border-color);\n  padding-left: 1em;\n}\n\n.contact-step[_ngcontent-%COMP%] {\n  color: var(--font-1);\n  line-height: 1.5;\n}',
